INSERT INTO company_profiles (name, slug, website, sources, last_checked)
VALUES ('Amazon', 'amazon', 'https://amazon.jobs', '[{"url": "https://amazon.jobs/content/en/how-we-hire/interview-loop", "title": "Amazon: Interview loop"}, {"url": "https://www.placementpreparation.io/amazon/recruitment-process/", "title": "Amazon SDE-1 fresher recruitment process (placementpreparation.io)"}]'::jsonb, '2026-10-15');

INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, sources, last_checked)
SELECT id, 'software_engineer', 'fresher', '[{"name": "Online assessment", "format": "HackerRank, proctored", "tests": "Coding challenge (two problems), work simulation and work style assessment tied to the leadership principles", "duration": "Reported 90 minutes to 2 hours"}, {"name": "Technical interview round 1", "format": "Virtual or on-site", "tests": "One or two data structures questions and leadership principle questions", "duration": "45 to 60 minutes"}, {"name": "Technical interview round 2", "format": "Virtual or on-site", "tests": "Trees, graphs, recursion and dynamic programming with follow-ups", "duration": "45 to 75 minutes"}, {"name": "Bar raiser", "format": "Interviewer from another team", "tests": "A demanding algorithm problem and leadership principle questions", "duration": "45 to 60 minutes"}, {"name": "Hiring manager discussion", "format": "Interview", "tests": "Team fit, location and compensation", "duration": null}]'::jsonb, '["arrays", "hashing", "trees", "graphs", "dynamic_programming", "behavioural_storytelling"]'::jsonb, NULL, 'Amazon''s page only says candidates meet current employees one by one and that each assesses different areas, and it points to the leadership principles and the STAR method. The round details above come from the second source and are reported for fresher SDE-1 hiring. The process is described as taking 4 to 10 weeks.', NULL, '[{"url": "https://amazon.jobs/content/en/how-we-hire/interview-loop", "title": "Amazon: Interview loop"}, {"url": "https://www.placementpreparation.io/amazon/recruitment-process/", "title": "Amazon SDE-1 fresher recruitment process (placementpreparation.io)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'amazon';

