SELECT id, 'software_engineer', 'all levels', '[{"name": "Resume screening", "format": "Recruiter review", "tests": "Fit between experience and the role", "duration": null}, {"name": "Phone screening", "format": "Recruiter call", "tests": "Whether the candidate is still qualified", "duration": "About 30 to 60 minutes"}, {"name": "Onsite interviews", "format": "Series of interviews", "tests": "Past experience and technical knowledge related to the role", "duration": "4 to 9 interviews depending on the role"}, {"name": "Hiring committee review", "format": "Committee reads a packet with feedback", "tests": "Decision from resume and interview feedback", "duration": null}]'::jsonb, '[]'::jsonb, 'Google''s own how-we-hire page did not show the process text when checked, so only this general description is used.', 'Only a general description is sourced, not one specific to software engineers. The source says the process can run over about eight weeks and that Google may be slow to respond.', NULL, '[{"url": "https://mentorcruise.com/blog/the-google-interview-process-25c6e/", "title": "The Google interview process (MentorCruise, 2022)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'google';

